#include <bits/stdc++.h>
using namespace std;

class Fenwick {
    int n;
    vector<long long> tree;
public:
    explicit Fenwick(int size) : n(size), tree(size + 1) {}
    void add(int position, long long change) {
        for (int i = position; i <= n; i += i & -i) {
            tree[i] += change;
        }
    }

    long long prefix_sum(int position) const {
        long long total = 0;
        for (int i = position; i > 0; i -= i & -i) {
            total += tree[i];
        }
        return total;
    }
    long long range_sum(int l, int r) const {
        return prefix_sum(r) - prefix_sum(l - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n + 1);
    Fenwick tree(n);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        tree.add(i, a[i]);
    }

    for (int query = 0; query < q; ++query) {
        int type;
        cin >> type;
        if (type == 1) {
            int position;
            long long value;
            cin >> position >> value;
            tree.add(position, value - a[position]);
            a[position] = value;
        } else {
            int l, r;
            cin >> l >> r;
            cout << tree.range_sum(l, r) << '\n';
        }
    }
}

